using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalGardenAudit{
static FinalGardenAudit(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalGardenAudit.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("FinalGardenAudit.request");Run();}
static void Run(){var log=new StringBuilder();try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).ToArray();var plot=all.Single(r=>r.name=="polySurface47");log.AppendLine("PLOT path="+AnimationUtility.CalculateTransformPath(plot.transform,null)+" bounds="+plot.bounds+" position="+plot.transform.position+" rotation="+plot.transform.eulerAngles+" scale="+plot.transform.lossyScale+" mesh="+AssetDatabase.GetAssetPath(plot.GetComponent<MeshFilter>().sharedMesh));foreach(var m in plot.sharedMaterials)log.AppendLine("PLOT material="+AssetDatabase.GetAssetPath(m)+" texture="+AssetDatabase.GetAssetPath(m.GetTexture("_BaseMap"))+" scale="+m.GetTextureScale("_BaseMap"));
foreach(var r in all.Where(r=>r.bounds.SqrDistance(plot.bounds.center)<25000&&(r.name.ToLower().Contains("tree")||r.name.ToLower().Contains("bench")||r.name.ToLower().Contains("light")||r.sharedMaterials.Any(m=>m&&m.name.ToLower().Contains("tree")))).OrderBy(r=>r.bounds.SqrDistance(plot.bounds.center)).Take(50))log.AppendLine("PROP "+r.name+" path="+AnimationUtility.CalculateTransformPath(r.transform,null)+" prefab="+PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(r.gameObject)+" bounds="+r.bounds+" scale="+r.transform.lossyScale+" rotation="+r.transform.eulerAngles+" materials="+string.Join("|",r.sharedMaterials.Select(m=>m?m.name:"null")));
log.AppendLine("GRASS USERS="+all.Count(r=>r.sharedMaterials.Contains(plot.sharedMaterial)));foreach(var t in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.name.StartsWith("Tree (")).Take(4))log.AppendLine("TREE "+AnimationUtility.CalculateTransformPath(t,null)+" renderers="+t.GetComponentsInChildren<Renderer>().Length+" bounds="+string.Join("|",t.GetComponentsInChildren<Renderer>().Select(r=>r.bounds.ToString()))+" scale="+t.lossyScale+" rot="+t.eulerAngles);var other=all.Single(r=>r.name=="polySurface742");log.AppendLine("PLOT742 "+AnimationUtility.CalculateTransformPath(other.transform,null)+" bounds="+other.bounds+" mat="+AssetDatabase.GetAssetPath(other.sharedMaterial));var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");foreach(var t in root.GetComponentsInChildren<Transform>(true).Where(t=>t.name.StartsWith("Sunken Underpass ")))foreach(var r in t.GetComponentsInChildren<Renderer>(true))log.AppendLine("UNDERPASS "+t.name+" "+r.name+" bounds="+r.bounds);
}catch(Exception e){log.AppendLine("FAILED "+e);}File.WriteAllText("FinalEnvironmentRoadReview/GardenAudit.txt",log.ToString());}}
